select p.user_id, sum(t.total_quantity - t.use_quantity) as total_quantity from tb_user_property as p join tb_user_property_type as t on p.id = t.property_id where p.user_id in
#{item}
and p.is_deleted = 0 and p.is_use = 1 and p.type = 0 and t.commodity_type_code = #{commodityCode} and t.is_deleted = 0 group by p.user_id
